const state = await appStore.getState();
const data = state && typeof state === "object" ? state : {};

const HABITS_KEY = "habits";
const LOGS_KEY = "checkins";

const habits = Array.isArray(data[HABITS_KEY]) ? data[HABITS_KEY].slice() : [];
const checkins = data[LOGS_KEY] && typeof data[LOGS_KEY] === "object" && !Array.isArray(data[LOGS_KEY])
  ? Object.assign({}, data[LOGS_KEY])
  : {};

const el = (role) => document.querySelector('[data-role="' + role + '"]');

const addForm = el("add-form");
const nameInput = el("name-input");
const addBtn = el("add-btn");
const formMsg = el("form-msg");
const listMsg = el("list-msg");
const habitList = el("habit-list");
const emptyBox = el("empty");
const doneCountEl = el("done-count");
const totalCountEl = el("total-count");
const progressEl = el("progress");
const todayLabel = el("today-label");
const clearDoneBtn = el("clear-done-btn");

const dialogMask = el("dialog-mask");
const dialogTitle = el("dialog-title");
const dialogText = el("dialog-text");
const dialogCancel = el("dialog-cancel");
const dialogConfirm = el("dialog-confirm");

function pad2(n) {
  return n < 10 ? "0" + n : String(n);
}

function todayKey() {
  const d = new Date();
  return d.getFullYear() + "-" + pad2(d.getMonth() + 1) + "-" + pad2(d.getDate());
}

function todayText() {
  const d = new Date();
  const week = ["周日", "周一", "周二", "周三", "周四", "周五", "周六"][d.getDay()];
  return d.getFullYear() + " 年 " + (d.getMonth() + 1) + " 月 " + d.getDate() + " 日 · " + week;
}

function dayLog(key) {
  const raw = checkins[key];
  if (raw && typeof raw === "object" && !Array.isArray(raw)) return raw;
  return {};
}

function isDoneToday(id) {
  return dayLog(todayKey())[id] === true;
}

function countDoneToday() {
  const log = dayLog(todayKey());
  let n = 0;
  for (let i = 0; i < habits.length; i++) {
    const h = habits[i];
    if (h && log[h.id] === true) n++;
  }
  return n;
}

function showMsg(node, text, ok) {
  if (!node) return;
  node.textContent = text || "";
  node.hidden = !text;
  node.classList.toggle("is-ok", !!ok);
}

function render() {
  const done = countDoneToday();
  const total = habits.length;
  doneCountEl.textContent = String(done);
  totalCountEl.textContent = String(total);
  const pct = total > 0 ? Math.round((done / total) * 100) : 0;
  progressEl.style.width = pct + "%";

  habitList.textContent = "";
  emptyBox.hidden = total > 0;
  clearDoneBtn.disabled = done === 0;

  for (let i = 0; i < habits.length; i++) {
    const h = habits[i];
    if (!h || typeof h !== "object") continue;
    const id = String(h.id);
    const doneToday = isDoneToday(id);

    const li = document.createElement("li");
    li.className = "habit-item" + (doneToday ? " is-done" : "");

    const check = document.createElement("button");
    check.type = "button";
    check.className = "check";
    check.setAttribute("aria-pressed", doneToday ? "true" : "false");
    check.setAttribute("aria-label", (doneToday ? "取消今天的打卡：" : "标记今天已完成：") + String(h.name || ""));
    check.textContent = "✓";
    check.addEventListener("click", () => {
      toggleToday(id);
    });

    const main = document.createElement("div");
    main.className = "habit-main";

    const nameEl = document.createElement("div");
    nameEl.className = "habit-name";
    nameEl.textContent = String(h.name || "");

    const meta = document.createElement("div");
    meta.className = "habit-meta";
    meta.textContent = doneToday ? "今天已完成" : "今天未完成";

    main.appendChild(nameEl);
    main.appendChild(meta);

    const del = document.createElement("button");
    del.type = "button";
    del.className = "btn-del";
    del.textContent = "删除";
    del.addEventListener("click", () => {
      askDelete(id, String(h.name || ""));
    });

    li.appendChild(check);
    li.appendChild(main);
    li.appendChild(del);
    habitList.appendChild(li);
  }
}

async function persist(nextHabits, nextCheckins) {
  const next = Object.assign({}, data);
  next[HABITS_KEY] = nextHabits;
  next[LOGS_KEY] = nextCheckins;
  await appStore.setState(next);
  data[HABITS_KEY] = nextHabits;
  data[LOGS_KEY] = nextCheckins;
}

async function toggleToday(id) {
  const key = todayKey();
  const nextCheckins = Object.assign({}, checkins);
  const log = Object.assign({}, dayLog(key));
  if (log[id] === true) {
    delete log[id];
  } else {
    log[id] = true;
  }
  nextCheckins[key] = log;
  try {
    await persist(habits.slice(), nextCheckins);
    checkins[key] = log;
    showMsg(listMsg, "");
    render();
  } catch (err) {
    showMsg(listMsg, "保存失败，请重试。");
  }
}

async function clearToday() {
  const key = todayKey();
  const nextCheckins = Object.assign({}, checkins);
  nextCheckins[key] = {};
  try {
    await persist(habits.slice(), nextCheckins);
    checkins[key] = {};
    showMsg(listMsg, "已取消今天的全部打卡。", true);
    render();
  } catch (err) {
    showMsg(listMsg, "保存失败，请重试。");
  }
}

function makeId() {
  return "h" + Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
}

async function addHabit(name) {
  const item = { id: makeId(), name: name, createdAt: new Date().toISOString() };
  const nextHabits = habits.concat([item]);
  try {
    await persist(nextHabits, Object.assign({}, checkins));
    habits.push(item);
    showMsg(formMsg, "已添加：" + name, true);
    render();
    return true;
  } catch (err) {
    showMsg(formMsg, "保存失败，习惯未添加，请重试。");
    return false;
  }
}

async function removeHabit(id) {
  const nextHabits = habits.filter((h) => !h || String(h.id) !== id);
  const nextCheckins = Object.assign({}, checkins);
  const keys = Object.keys(nextCheckins);
  for (let i = 0; i < keys.length; i++) {
    const k = keys[i];
    const log = nextCheckins[k];
    if (log && typeof log === "object" && !Array.isArray(log) && Object.prototype.hasOwnProperty.call(log, id)) {
      const copy = Object.assign({}, log);
      delete copy[id];
      nextCheckins[k] = copy;
    }
  }
  try {
    await persist(nextHabits, nextCheckins);
    const idx = habits.findIndex((h) => h && String(h.id) === id);
    if (idx >= 0) habits.splice(idx, 1);
    checkins = nextCheckins;
    showMsg(listMsg, "已删除该习惯。", true);
    render();
  } catch (err) {
    showMsg(listMsg, "保存失败，删除未生效，请重试。");
  }
}

let pendingDeleteId = null;

function closeDialog() {
  pendingDeleteId = null;
  dialogMask.hidden = true;
}

function askDelete(id, name) {
  pendingDeleteId = id;
  dialogTitle.textContent = "确认删除";
  dialogText.textContent = "确定要删除习惯「" + name + "」吗？该习惯的打卡记录也会一并移除，此操作不可撤销。";
  dialogMask.hidden = false;
  dialogConfirm.focus();
}

dialogCancel.addEventListener("click", closeDialog);
dialogMask.addEventListener("click", (e) => {
  if (e.target === dialogMask) closeDialog();
});
document.addEventListener("keydown", (e) => {
  if (e.key === "Escape" && !dialogMask.hidden) closeDialog();
});
dialogConfirm.addEventListener("click", async () => {
  const id = pendingDeleteId;
  closeDialog();
  if (id) await removeHabit(id);
});

addForm.addEventListener("submit", async (e) => {
  e.preventDefault();
  const raw = nameInput.value;
  const name = raw.trim();
  if (!name) {
    showMsg(formMsg, "请输入习惯名称。");
    nameInput.focus();
    return;
  }
  const dup = habits.some((h) => h && String(h.name || "").trim() === name);
  if (dup) {
    showMsg(formMsg, "已存在同名习惯，请换一个名称。");
    nameInput.focus();
    return;
  }
  addBtn.disabled = true;
  const ok = await addHabit(name);
  addBtn.disabled = false;
  if (ok) {
    nameInput.value = "";
    nameInput.focus();
  }
});

clearDoneBtn.addEventListener("click", async () => {
  clearDoneBtn.disabled = true;
  await clearToday();
  render();
});

todayLabel.textContent = todayText();
render();

