:root {
  --bg: #f4f6fb;
  --card: #ffffff;
  --ink: #1f2430;
  --ink-soft: #6b7280;
  --line: #e4e8f0;
  --brand: #3b6ef5;
  --brand-soft: #eaf0ff;
  --ok: #17a673;
  --danger: #d64545;
  --radius: 14px;
}

* { box-sizing: border-box; }

.wrap {
  max-width: 640px;
  margin: 0 auto;
  padding: 20px 16px 48px;
  color: var(--ink);
  font-family: system-ui, -apple-system, "PingFang SC", "Microsoft YaHei", sans-serif;
  font-size: 15px;
  line-height: 1.5;
}

.hero { margin-bottom: 18px; }

.hero-title {
  margin: 0 0 4px;
  font-size: 24px;
  font-weight: 700;
  letter-spacing: 0.5px;
}

.hero-sub {
  margin: 0 0 14px;
  color: var(--ink-soft);
  font-size: 13px;
}

.stat-card {
  background: linear-gradient(135deg, #3b6ef5, #6f8ffb);
  color: #fff;
  border-radius: var(--radius);
  padding: 16px 18px 14px;
  box-shadow: 0 8px 20px rgba(59, 110, 245, 0.22);
}

.stat-main {
  display: flex;
  align-items: baseline;
  gap: 6px;
}

.stat-num {
  font-size: 34px;
  font-weight: 700;
  line-height: 1;
}

.stat-total {
  font-size: 16px;
  opacity: 0.85;
}

.stat-text {
  margin-top: 4px;
  font-size: 13px;
  opacity: 0.9;
}

.progress-track {
  margin-top: 12px;
  height: 7px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.28);
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  width: 0%;
  border-radius: 999px;
  background: #ffffff;
  transition: width 0.25s ease;
}

.panel {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 16px;
  margin-bottom: 16px;
}

.panel-title {
  margin: 0 0 12px;
  font-size: 16px;
  font-weight: 600;
}

.list-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  flex-wrap: wrap;
}

.list-head .panel-title { margin-bottom: 0; }

.add-form {
  display: flex;
  gap: 10px;
  align-items: flex-end;
  flex-wrap: wrap;
}

.field {
  flex: 1 1 200px;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.field-label {
  font-size: 13px;
  color: var(--ink-soft);
}

.input {
  width: 100%;
  padding: 10px 12px;
  border: 1px solid var(--line);
  border-radius: 10px;
  font-size: 15px;
  color: var(--ink);
  background: #fbfcfe;
  outline: none;
}

.input:focus {
  border-color: var(--brand);
  background: #fff;
  box-shadow: 0 0 0 3px var(--brand-soft);
}

.btn {
  border: 1px solid transparent;
  border-radius: 10px;
  padding: 10px 16px;
  font-size: 14px;
  font-family: inherit;
  cursor: pointer;
  white-space: nowrap;
  transition: background 0.15s ease, border-color 0.15s ease, color 0.15s ease;
}

.btn-primary {
  background: var(--brand);
  color: #fff;
}

.btn-primary:hover { background: #2f5fe0; }

.btn-ghost {
  background: #fff;
  color: var(--ink-soft);
  border-color: var(--line);
}

.btn-ghost:hover {
  color: var(--ink);
  border-color: #c9d2e3;
}

.btn-danger {
  background: var(--danger);
  color: #fff;
}

.btn-danger:hover { background: #bf3a3a; }

.btn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.msg {
  margin: 10px 0 0;
  font-size: 13px;
  color: var(--danger);
}

.msg.is-ok { color: var(--ok); }

.habit-list {
  list-style: none;
  margin: 12px 0 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.habit-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: #fbfcfe;
}

.habit-item.is-done {
  border-color: #bfe6d6;
  background: #f2fbf7;
}

.check {
  flex: 0 0 auto;
  width: 26px;
  height: 26px;
  border-radius: 8px;
  border: 2px solid #c6cfe0;
  background: #fff;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  color: transparent;
  font-size: 15px;
  line-height: 1;
}

.check:hover { border-color: var(--brand); }

.habit-item.is-done .check {
  background: var(--ok);
  border-color: var(--ok);
  color: #fff;
}

.habit-main {
  flex: 1 1 auto;
  min-width: 0;
}

.habit-name {
  font-size: 15px;
  word-break: break-word;
}

.habit-item.is-done .habit-name {
  color: #4b5563;
  text-decoration: line-through;
}

.habit-meta {
  margin-top: 2px;
  font-size: 12px;
  color: var(--ink-soft);
}

.btn-del {
  flex: 0 0 auto;
  background: #fff;
  border: 1px solid var(--line);
  color: var(--ink-soft);
  border-radius: 9px;
  padding: 7px 12px;
  font-size: 13px;
  font-family: inherit;
  cursor: pointer;
}

.btn-del:hover {
  color: var(--danger);
  border-color: #f0c4c4;
  background: #fff6f6;
}

.empty {
  margin-top: 12px;
  padding: 26px 16px;
  text-align: center;
  border: 1px dashed var(--line);
  border-radius: 12px;
  background: #fbfcfe;
}

.empty-title {
  margin: 0 0 4px;
  font-weight: 600;
}

.empty-text {
  margin: 0;
  font-size: 13px;
  color: var(--ink-soft);
}

.dialog-mask {
  position: fixed;
  inset: 0;
  background: rgba(20, 24, 34, 0.45);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  z-index: 50;
}

.dialog-mask[hidden] { display: none; }

.dialog {
  width: 100%;
  max-width: 340px;
  background: #fff;
  border-radius: var(--radius);
  padding: 18px;
  box-shadow: 0 18px 40px rgba(15, 20, 35, 0.25);
}

.dialog-title {
  margin: 0 0 8px;
  font-size: 17px;
}

.dialog-text {
  margin: 0 0 16px;
  font-size: 14px;
  color: var(--ink-soft);
  word-break: break-word;
}

.dialog-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
}

@media (max-width: 420px) {
  .add-form { flex-direction: column; align-items: stretch; }
  .btn-primary { width: 100%; }
}
